package org.brightstats.data;

import java.io.*;
import java.nio.file.*;
import java.util.*;
import org.apache.poi.ss.usermodel.*;
import org.apache.poi.xssf.usermodel.XSSFCell;
import org.apache.poi.xssf.usermodel.XSSFWorkbook;
import org.apache.poi.hssf.usermodel.HSSFWorkbook;

/** XLS/XLSX data interchange. Formula caches are read; formulas/macros are never executed. */
public final class WorkbookData {
    private WorkbookData(){}
    public record Sheet(String name,int firstRow,int lastRow,boolean hidden){}
    public record Imported(String sheet,DataPreparation.Raw raw,List<String> warnings){public Imported{warnings=List.copyOf(warnings);}}
    private static void checkFile(Path path)throws IOException{if(!Files.isRegularFile(path)||Files.size(path)>64L*1024*1024)throw new IOException("Choose an XLS/XLSX workbook of at most 64 MiB.");}
    public static List<Sheet> sheets(Path path)throws IOException{checkFile(path);try(var input=Files.newInputStream(path);var workbook=WorkbookFactory.create(input)){List<Sheet> result=new ArrayList<>();for(int index=0;index<workbook.getNumberOfSheets();index++){var sheet=workbook.getSheetAt(index);result.add(new Sheet(sheet.getSheetName(),sheet.getFirstRowNum(),sheet.getLastRowNum(),workbook.isSheetHidden(index)||workbook.isSheetVeryHidden(index)));}if(result.isEmpty())throw new IOException("Workbook has no worksheets.");return List.copyOf(result);}catch(RuntimeException invalid){throw new IOException("Cannot read workbook: "+invalid.getMessage(),invalid);}}
    public static Imported read(Path path,String sheetName,int headerRow)throws IOException{checkFile(path);if(headerRow<0)throw new IOException("Header row must be nonnegative.");try(var input=Files.newInputStream(path);var workbook=WorkbookFactory.create(input)){var sheet=sheetName==null?workbook.getSheetAt(0):workbook.getSheet(sheetName);if(sheet==null)throw new IOException("Worksheet not found: "+sheetName);var header=sheet.getRow(headerRow);if(header==null||header.getLastCellNum()<1)throw new IOException("The selected header row is empty.");int columns=header.getLastCellNum();if(columns>16384||sheet.getLastRowNum()-headerRow>1000000||(long)(sheet.getLastRowNum()-headerRow)*columns>5000000)throw new IOException("Worksheet exceeds the supported data dimensions.");List<String> names=new ArrayList<>();for(int column=0;column<columns;column++)names.add(value(header.getCell(column),new int[2]));List<List<String>> rows=new ArrayList<>();int[] counts=new int[2];for(int index=headerRow+1;index<=sheet.getLastRowNum();index++){var source=sheet.getRow(index);List<String> row=new ArrayList<>();for(int column=0;column<columns;column++)row.add(value(source==null?null:source.getCell(column),counts));if(source!=null&&source.getLastCellNum()>columns)for(int column=columns;column<source.getLastCellNum();column++)if(!value(source.getCell(column),counts).isBlank())throw new IOException("Data extends beyond the header at worksheet row "+(index+1));rows.add(List.copyOf(row));}if(rows.isEmpty())throw new IOException("Worksheet has no observations after its header.");List<String> warnings=new ArrayList<>();if(counts[0]>0)warnings.add(counts[0]+" formula cells were read from saved cached results; no formula, macro, external link or program was executed. Cached results can be stale.");if(counts[1]>0)warnings.add(counts[1]+" date/time cells were imported as ISO local date/time text; Excel values have no time zone.");warnings.add("Worksheet row positions, blank cells and original text are preserved. Review column definitions and missing-value treatment before import.");return new Imported(sheet.getSheetName(),new DataPreparation.Raw(names,rows),warnings);}catch(RuntimeException invalid){throw new IOException("Cannot read worksheet: "+invalid.getMessage(),invalid);}}
    private static String value(Cell cell,int[] counts)throws IOException{if(cell==null)return "";CellType type=cell.getCellType();if(type==CellType.FORMULA){counts[0]++;if(cell instanceof XSSFCell xml&&(!xml.getCTCell().isSetV()||xml.getCTCell().getV()==null||xml.getCTCell().getV().isBlank()))throw new IOException("Formula at "+cell.getAddress()+" has no saved result. Recalculate/save the workbook in its spreadsheet application first.");type=cell.getCachedFormulaResultType();}return switch(type){case BLANK,_NONE->"";case STRING->cell.getStringCellValue();case BOOLEAN->Boolean.toString(cell.getBooleanCellValue());case NUMERIC->{double number=cell.getNumericCellValue();if(!Double.isFinite(number))throw new IOException("Nonfinite workbook number at "+cell.getAddress());if(DateUtil.isCellDateFormatted(cell)){if(!DateUtil.isValidExcelDate(number))throw new IOException("Invalid Excel date at "+cell.getAddress());counts[1]++;yield cell.getLocalDateTimeCellValue().toString();}yield Double.toString(number);}case ERROR->throw new IOException("Spreadsheet error at "+cell.getAddress()+": "+FormulaError.forInt(cell.getErrorCellValue()).getString());default->throw new IOException("Unsupported cell type at "+cell.getAddress());};}
    public static void write(Path path,String sheetName,DataPreparation.Raw data,boolean xlsx)throws IOException{Objects.requireNonNull(data);if(data.headers().size()>(xlsx?16384:256)||data.rows().size()>(xlsx?1048575:65535)||(long)data.rows().size()*data.headers().size()>5000000)throw new IOException("Data exceeds the workbook format limits.");if(Files.exists(path))throw new FileAlreadyExistsException(path.toString());try(Workbook workbook=xlsx?new XSSFWorkbook():new HSSFWorkbook()){var sheet=workbook.createSheet(sheetName==null?"Data":sheetName);var header=sheet.createRow(0);for(int column=0;column<data.headers().size();column++)header.createCell(column,CellType.STRING).setCellValue(data.headers().get(column));for(int index=0;index<data.rows().size();index++){var row=sheet.createRow(index+1);for(int column=0;column<data.headers().size();column++){String value=data.rows().get(index).get(column);row.createCell(column,CellType.STRING).setCellValue(value);}}sheet.createFreezePane(0,1);try(var output=Files.newOutputStream(path,StandardOpenOption.CREATE_NEW,StandardOpenOption.WRITE)){workbook.write(output);}}}
    public static String delimited(DataPreparation.Raw data){StringBuilder text=new StringBuilder();List<List<String>> rows=new ArrayList<>();rows.add(data.headers());rows.addAll(data.rows());for(var row:rows){for(int column=0;column<row.size();column++){if(column>0)text.append('\t');text.append('"').append(row.get(column).replace("\"","\"\"")).append('"');}text.append('\n');}return text.toString();}
}
